48	Generates Verilog RTL from a given IR file. Writes a Verilog file and a module
49	signature describing the module interface to a specified location. Example
50	invocations:
51	
52	Emit combinational module:
53	   codegen_main --generator=combinational --output_verilog_path=DIR IR_FILE
54	
55	Emit a feed-forward pipelined module:
56	   codegen_main --generator=pipeline \
57	       --clock_period_ps=500 \
58	       --pipeline_stages=7 \
59	       IR_FILE
60	)";
61	
62	namespace xls {
63	namespace {
64	
65	absl::Status RealMain(std::string_view ir_path) {
66	  auto timeout = StartTimeoutTimer();
67	  if (ir_path == "-") {
68	    ir_path = "/dev/stdin";
69	  }
70	  XLS_ASSIGN_OR_RETURN(std::string ir_contents, GetFileContents(ir_path));
71	  XLS_ASSIGN_OR_RETURN(std::unique_ptr<Package> p,
72	                       Parser::ParsePackage(ir_contents, ir_path));
73	
74	  XLS_ASSIGN_OR_RETURN(CodegenFlagsProto codegen_flags_proto,
75	                       GetCodegenFlags());
76	  if (p->ChannelsAreProcScoped()) {
77	    codegen_flags_proto.set_codegen_version(CODEGEN_VERSION_ONE_DOT_FIVE);
78	  }
79	  if (codegen_flags_proto.has_reference_residual_data()) {
80	    return absl::UnimplementedError(
81	        "Reference residual data is not supported in codegen_main; use "
82	        "block_to_verilog_main");
83	  }
84	  if (!codegen_flags_proto.top().empty() && !p->GetTop().has_value()) {
85	    XLS_RETURN_IF_ERROR(p->SetTopByName(codegen_flags_proto.top()));
86	  }
87	
88	  XLS_RET_CHECK(p->GetTop().has_value())
89	      << "Package " << p->name() << " needs a top function/proc.";
90	
91	  XLS_ASSIGN_OR_RETURN(
92	      SchedulingOptionsFlagsProto scheduling_options_flags_proto,
93	      GetSchedulingOptionsFlagsProto());
94	  XLS_ASSIGN_OR_RETURN(
95	      bool delay_model_flag_passed,
96	      IsDelayModelSpecifiedViaFlag(scheduling_options_flags_proto));
97	
98	  SchedulingResult scheduling_result;
99	  if (codegen_flags_proto.generator() == GENERATOR_KIND_PIPELINE) {
100	    XLS_ASSIGN_OR_RETURN(
101	        scheduling_result,
102	        Schedule(p.get(), scheduling_options_flags_proto, codegen_flags_proto));
103	  }
104	  XLS_ASSIGN_OR_RETURN(
105	      PackageSchedule schedules,
106	      PackageSchedule::FromProto(p.get(), scheduling_result.package_schedule));
107	
108	  if (!absl::GetFlag(FLAGS_output_schedule_ir_path).empty()) {
109	    XLS_RETURN_IF_ERROR(SetFileContents(
110	        absl::GetFlag(FLAGS_output_schedule_ir_path), p->DumpIr()));
111	  }
112	
113	  if (!absl::GetFlag(FLAGS_output_schedule_path).empty()) {
114	    XLS_RETURN_IF_ERROR(
115	        SetTextProtoFile(absl::GetFlag(FLAGS_output_schedule_path),
116	                         scheduling_result.package_schedule));
117	  }
118	
119	  if (!absl::GetFlag(FLAGS_output_scheduling_pass_metrics_path).empty()) {
120	    XLS_RETURN_IF_ERROR(SetTextProtoFile(
121	        absl::GetFlag(FLAGS_output_scheduling_pass_metrics_path),
122	        scheduling_result.pass_pipeline_metrics));
123	  }
124	
125	  XLS_ASSIGN_OR_RETURN(
126	      verilog::CodegenResult codegen_result,
127	      Codegen(p.get(), scheduling_options_flags_proto, codegen_flags_proto,
128	              delay_model_flag_passed, &schedules));
129	
130	  if (!absl::GetFlag(FLAGS_output_block_ir_path).empty()) {
131	    QCHECK_GE(p->blocks().size(), 1)
132	        << "There should be at least one block in the package after generating "
133	           "module text.";
134	    XLS_RETURN_IF_ERROR(SetFileContents(
135	        absl::GetFlag(FLAGS_output_block_ir_path), p->DumpIr()));
136	  }
137	
138	  if (!absl::GetFlag(FLAGS_output_signature_path).empty()) {
139	    XLS_RETURN_IF_ERROR(
140	        SetTextProtoFile(absl::GetFlag(FLAGS_output_signature_path),
141	                         codegen_result.signature.proto()));
142	  }
143	
144	  if (!absl::GetFlag(FLAGS_output_codegen_pass_metrics_path).empty()) {
145	    XLS_RETURN_IF_ERROR(
146	        SetTextProtoFile(absl::GetFlag(FLAGS_output_codegen_pass_metrics_path),
147	                         codegen_result.pass_pipeline_metrics));
148	  }
149	
150	  if (!absl::GetFlag(FLAGS_block_metrics_path).empty()) {
151	    XLS_RETURN_IF_ERROR(SetTextProtoFile(
152	        absl::GetFlag(FLAGS_block_metrics_path), codegen_result.block_metrics));
153	  }
154	
155	  if (!absl::GetFlag(FLAGS_output_residual_data_path).empty()) {
156	    XLS_RETURN_IF_ERROR(
157	        SetTextProtoFile(absl::GetFlag(FLAGS_output_residual_data_path),
158	                         codegen_result.residual_data));
159	  }
160	
161	  const std::string& verilog_path = absl::GetFlag(FLAGS_output_verilog_path);
162	  if (!verilog_path.empty()) {
163	    for (int64_t i = 0; i < codegen_result.verilog_line_map.mapping_size();
