44	namespace xls::dslx {
45	namespace {
46	
47	static constexpr std::string_view kUsage = R"(
48	Converts a DSLX input file (and optional entry point) to XLS IR.
49	
50	Successfully converted XLS IR is printed to stdout; errors are printed to
51	stderr.
52	
53	Example invocation for a particular function:
54	
55	  ir_converter_main -entry best_function path/to/frobulator.x
56	
57	If no entry point is given all functions within the module are converted:
58	
59	  ir_converter_main path/to/frobulator.x
60	)";
61	
62	absl::Status RealMain(absl::Span<const std::string_view> paths) {
63	  XLS_ASSIGN_OR_RETURN(IrConverterOptionsFlagsProto ir_converter_options,
64	                       GetIrConverterOptionsFlagsProto());
65	
66	  std::optional<std::filesystem::path> output_file =
67	      ir_converter_options.has_output_file()
68	          ? std::make_optional<std::filesystem::path>(
69	                ir_converter_options.output_file())
70	          : std::nullopt;
71	
72	  std::string_view dslx_stdlib_path = ir_converter_options.dslx_stdlib_path();
73	  std::string_view dslx_path = ir_converter_options.dslx_path();
74	  std::vector<std::string_view> dslx_path_strs = absl::StrSplit(dslx_path, ':');
75	
76	  std::vector<std::filesystem::path> dslx_paths;
77	  dslx_paths.reserve(dslx_path_strs.size());
78	  for (const auto& path : dslx_path_strs) {
79	    dslx_paths.push_back(std::filesystem::path(path));
80	  }
81	
82	  std::optional<std::string_view> top;
83	  if (ir_converter_options.has_top()) {
84	    top = ir_converter_options.top();
85	  }
86	
87	  std::optional<std::string_view> package_name;
88	  if (ir_converter_options.has_package_name()) {
89	    package_name = ir_converter_options.package_name();
90	  }
91	
92	  std::vector<std::string> configured_values;
93	  if (ir_converter_options.configured_values_size() > 0) {
94	    configured_values.assign(ir_converter_options.configured_values().begin(),
95	                             ir_converter_options.configured_values().end());
96	  }
97	
98	  bool emit_assert = ir_converter_options.emit_assert();
99	  bool verify_ir = ir_converter_options.verify();
100	  bool convert_tests = ir_converter_options.convert_tests();
101	  bool warnings_as_errors = ir_converter_options.warnings_as_errors();
102	  bool type_inference_v2 = ir_converter_options.type_inference_v2();
103	  bool lower_to_proc_scoped_channels =
104	      ir_converter_options.has_lower_to_proc_scoped_channels()
105	          ? ir_converter_options.lower_to_proc_scoped_channels()
106	          : true;
107	  bool force_implicit_token_calling_convention =
108	      ir_converter_options.force_implicit_token_calling_convention();
109	  bool emit_trace = ir_converter_options.emit_trace();
110	  bool emit_cover = ir_converter_options.emit_cover();
111	
112	  // Start with the default set, then enable the to-enable and then disable the
113	  // to-disable.
114	  XLS_ASSIGN_OR_RETURN(
115	      WarningKindSet warnings,
116	      GetWarningsSetFromFlags(ir_converter_options.enable_warnings(),
117	                              ir_converter_options.disable_warnings()));
118	  std::optional<FifoConfig> default_fifo_config;
119	  if (ir_converter_options.has_default_fifo_config()) {
120	    XLS_ASSIGN_OR_RETURN(
121	        default_fifo_config,
122	        FifoConfig::FromProto(ir_converter_options.default_fifo_config()));
123	  }
124	  const ConvertOptions convert_options = {
125	      .emit_positions = true,
126	      .emit_assert = emit_assert,
127	      .emit_trace = emit_trace,
128	      .emit_cover = emit_cover,
129	      .verify_ir = verify_ir,
130	      .warnings_as_errors = warnings_as_errors,
131	      .warnings = warnings,
132	      .convert_tests = convert_tests,
133	      .default_fifo_config = default_fifo_config,
134	      .type_inference_v2 = type_inference_v2,
135	      .lower_to_proc_scoped_channels = lower_to_proc_scoped_channels,
136	      .force_implicit_token_calling_convention =
137	          force_implicit_token_calling_convention,
138	      .configured_values = configured_values,
139	  };
140	
141	  // The following checks are performed inside ConvertFilesToPackage(), but we
142	  // reproduce them here to give nicer error messages.
143	  if (!package_name.has_value()) {
144	    QCHECK_EQ(paths.size(), 1)
145	        << "-package_name *must* be given when multiple input paths are "
146	           "supplied";
147	  }
148	  if (paths.size() > 1) {
149	    QCHECK(!top.has_value())
150	        << "-entry cannot be supplied with multiple input paths (need a single "
151	           "input path to know where to resolve the entry function)";
152	  }
153	
154	  bool printed_error = false;
155	  XLS_ASSIGN_OR_RETURN(PackageConversionData result,
156	                       ConvertFilesToPackage(
157	                           paths, dslx_stdlib_path, dslx_paths, convert_options,
158	                           /*top=*/top,
159	                           /*package_name=*/package_name, &printed_error));
160	  if (output_file) {
161	    XLS_RETURN_IF_ERROR(SetFileContents(*output_file, result.DumpIr()));
162	  } else {
163	    std::cout << result.package->DumpIr();
164	  }
165	  if (ir_converter_options.has_interface_proto_file()) {
166	    XLS_RETURN_IF_ERROR(
167	        SetFileContents(ir_converter_options.interface_proto_file(),
168	                        result.interface.SerializeAsString()));
169	  }
170	  if (ir_converter_options.has_interface_textproto_file()) {
171	    std::string res;
172	    XLS_RET_CHECK(google::protobuf::TextFormat::PrintToString(result.interface, &res));
173	    XLS_RETURN_IF_ERROR(
174	        SetFileContents(ir_converter_options.interface_textproto_file(), res));
175	  }
176	
177	  if (printed_error) {
178	    return absl::InternalError(
179	        "IR conversion failed with an earlier non-fatal error.");
180	  }
181	
182	  return absl::OkStatus();
183	}
184	
185	}  // namespace
186	}  // namespace xls::dslx
