188	int main(int argc, char* argv[]) {
189	  std::vector<std::string_view> args =
190	      xls::InitXls(xls::dslx::kUsage, argc, argv);
191	  if (args.empty()) {
192	    LOG(QFATAL) << "Wrong number of command-line arguments; got " << args.size()
193	                << ": `" << absl::StrJoin(args, " ") << "`; want " << argv[0]
194	                << " <input-file>";
195	  }
196	  // "-" is a special path that is shorthand for /dev/stdin. Update here as
197	  // there isn't a better place later.
198	  for (auto& arg : args) {
